describe('Filtered Search URL Sharing', () => {
    beforeEach(() => {
        cy.visit('/search');
        cy.get('input[name="search"]').type('Cypress');
        cy.get('select[name="filter"]').select('Latest');
        cy.get('button[type="submit"]').click();
    });

    it('should generate a shareable URL after applying filters', () => {
        cy.url().should('include', 'search?q=Cypress&filter=Latest');
        cy.get('.share-url-button').click();
        cy.get('.share-url-input').should('have.value', cy.url());
    });

    it('should handle empty search input gracefully', () => {
        cy.get('input[name="search"]').clear();
        cy.get('button[type="submit"]').click();
        cy.url().should('include', 'search?q=&filter=Latest');
        cy.get('.error-message').should('be.visible').and('contain', 'Please enter a search term');
    });
});
